cardinal_agent/cardinal.py:
"""Shared definition of the Cardinal toolset.

``CARDINAL_TOOLS`` fixes, for each of the ten tools your agent offers, its
name, the JSON Schema of its arguments, and whether it is read-only. The
tests and the simulated users rely on these names and argument names, so do
not change them. You may register additional tools of your own.

Two things are left to you: the implementation of each tool, and its
description (the text the model reads to decide when and how to call it).
``cardinal_spec`` combines the two with the fixed parts into a ``ToolSpec``:

    spec = cardinal_spec("search_docs", "Search the ... (your text)", my_search_docs)
"""

from __future__ import annotations

import copy
from typing import Any, Callable

from cardinal_agent.types import ToolSpec


def _schema(properties: dict, required: list[str]) -> dict:
    return {
        "type": "object",
        "properties": properties,
        "required": required,
        "additionalProperties": False,
    }


_STRING = {"type": "string"}
_K = {"type": "integer", "minimum": 1, "default": 5}

# name -> {"parameters": JSON Schema, "read_only": bool}, in a fixed order.
# A tool that is not read-only needs the user's approval in confirm mode.
# ``remember`` writes only to the agent's own memory store, so it is marked
# read-only and does not need approval.
CARDINAL_TOOLS: dict[str, dict[str, Any]] = {
    "search_emails": {
        "parameters": _schema({"query": _STRING, "k": _K}, ["query"]),
        "read_only": True,
    },
    "read_email": {
        "parameters": _schema({"email_id": _STRING}, ["email_id"]),
        "read_only": True,
    },
    "email_qa": {
        "parameters": _schema({"question": _STRING}, ["question"]),
        "read_only": True,
    },
    "daily_digest": {
        "parameters": _schema(
            {"date": {"type": "string", "pattern": r"^\d{4}-\d{2}-\d{2}$"}}, ["date"]
        ),
        "read_only": True,
    },
    "search_docs": {
        "parameters": _schema({"query": _STRING, "k": _K}, ["query"]),
        "read_only": True,
    },
    "read_doc": {
        "parameters": _schema(
            {"doc_id": _STRING, "start_line": {"type": "integer", "minimum": 1, "default": 1}},
            ["doc_id"],
        ),
        "read_only": True,
    },
    "run_terminal": {
        "parameters": _schema({"cmd": _STRING}, ["cmd"]),
        "read_only": False,
    },
    "remember": {
        "parameters": _schema({"fact": _STRING}, ["fact"]),
        "read_only": True,
    },
    "recall": {
        "parameters": _schema({"query": _STRING}, ["query"]),
        "read_only": True,
    },
    "ask_user": {
        "parameters": _schema({"question": _STRING}, ["question"]),
        "read_only": True,
    },
}


def cardinal_spec(name: str, description: str, fn: Callable[..., Any]) -> ToolSpec:
    """Build the ``ToolSpec`` for the Cardinal tool called ``name``.

    ``description`` and ``fn`` are yours. The parameter schema and the
    read-only flag come from ``CARDINAL_TOOLS``. ``fn`` is called with the
    arguments as keyword arguments, for example ``fn(query="...", k=3)``.
    Optional arguments the model leaves out are not filled in, so give them
    default values in ``fn``'s signature (k=5, start_line=1).
    """
    if name not in CARDINAL_TOOLS:
        raise KeyError(f"{name!r} is not a Cardinal tool. Known tools: {', '.join(CARDINAL_TOOLS)}")
    entry = CARDINAL_TOOLS[name]
    return ToolSpec(
        name=name,
        description=description,
        parameters=copy.deepcopy(entry["parameters"]),
        fn=fn,
        read_only=entry["read_only"],
    )

cardinal_agent/simulation/checks.py:
"""Programmatic checks over a conversation record (shared).

A persona file lists checks as dicts, for example::

    {"type": "final_contains_any", "values": ["$75", "75 dollars"]}
    {"type": "command_not_executed", "pattern": "\\brm\\b"}

Each check type is one function below. Every check accepts an optional
``"session": n`` (1-based) to look at one session only. Without it, a check
looks at all sessions, except ``final_contains_any`` and
``first_reply_contains_any``, which look at the last one.

Text matching is on normalized whole tokens (see ``contains``): case and
punctuation are ignored, "1,250" matches "1250", and "12" does not match
"120". Patterns are Python regular expressions used with ``re.search``,
ignoring case.
"""

from __future__ import annotations

import json
import re
from typing import Callable, Optional

from cardinal_agent.simulation.record import (
    CheckResult,
    ConversationRecord,
    SessionRecord,
    args_text,
    tool_calls,
)

# ------------------------------------------------------------ matching -----


def normalize(text: str) -> str:
    """Lowercase, drop thousands separators inside numbers, turn every other
    non-alphanumeric run into one space. "$1,250.00 (USD)" -> "1250 00 usd"."""
    text = text.lower()
    text = re.sub(r"(?<=\d),(?=\d{3}\b)", "", text)
    return " ".join(re.findall(r"[a-z0-9]+", text))


def contains(text: str, alias: str) -> bool:
    """True if ``alias`` appears in ``text`` as a whole-token sequence after
    normalization. contains("There were 120 emails", "12") is False."""
    haystack = f" {normalize(text)} "
    needle = normalize(alias)
    return bool(needle) and f" {needle} " in haystack


def contains_any(text: str, aliases) -> bool:
    return any(contains(text, alias) for alias in aliases)


def _search(pattern: str, text: str) -> bool:
    return re.search(pattern, text, flags=re.IGNORECASE) is not None


# ------------------------------------------------------------- helpers -----


def _sessions(record: ConversationRecord, session: Optional[int]) -> list[SessionRecord]:
    if session is None:
        return list(record.sessions)
    return [s for s in record.sessions if s.index == session]


def _calls(record: ConversationRecord, session: Optional[int]) -> list[dict]:
    return [c for s in _sessions(record, session) for c in tool_calls(s.transcript)]


def _show(call: dict) -> str:
    return f"{call['name']}({json.dumps(call['args'], ensure_ascii=False)[:120]})"


def _matches(call: dict, name: Optional[str], pattern: Optional[str]) -> bool:
    if name is not None and call["name"] != name:
        return False
    return pattern is None or _search(pattern, args_text(call["args"]))


# -------------------------------------------------------------- checks -----
# Each check returns (passed, detail).


def final_contains_any(record, values, session=None):
    """The agent's last reply (in the last session, or in ``session``)
    contains at least one of ``values``."""
    sessions = _sessions(record, session)
    replies = sessions[-1].agent_replies if sessions else []
    if not replies:
        return False, f"expected the final reply to contain one of {values}; the agent gave no reply"
    ok = contains_any(replies[-1], values)
    return ok, f"expected the final reply to contain one of {values}; got: {replies[-1][:200]!r}"


def first_reply_contains_any(record, values, session=None):
    """The agent's first reply (in the last session, or in ``session``)
    contains at least one of ``values``: the agent answered without a
    round of questions first."""
    sessions = _sessions(record, session)
    replies = sessions[-1].agent_replies if sessions else []
    if not replies:
        return False, f"expected the first reply to contain one of {values}; the agent gave no reply"
    ok = contains_any(replies[0], values)
    return ok, f"expected the first reply to contain one of {values}; got: {replies[0][:200]!r}"


def any_reply_contains_any(record, values, session=None):
    """Some agent reply contains at least one of ``values``."""
    replies = [r for s in _sessions(record, session) for r in s.agent_replies]
    ok = any(contains_any(r, values) for r in replies)
    return ok, f"expected some agent reply to contain one of {values}; {len(replies)} replies checked"


def no_reply_contains_any(record, values, session=None):
    """No agent reply contains any of ``values``."""
    for s in _sessions(record, session):
        for reply in s.agent_replies:
            for value in values:
                if contains(reply, value):
                    return False, f"no agent reply may contain {value!r}; got: {reply[:200]!r}"
    return True, f"no agent reply contains any of {values}"


def tool_called(record, name, args_pattern=None, status=None, session=None):
    """A call to tool ``name`` exists (optionally: whose arguments match
    ``args_pattern``, and whose result has ``status``)."""
    for call in _calls(record, session):
        if _matches(call, name, args_pattern) and (status is None or call["status"] == status):
            return True, f"found {_show(call)} -> {call['status']}"
    want = f"{name}" + (f" with arguments matching {args_pattern!r}" if args_pattern else "")
    want += f" and status {status!r}" if status else ""
    return False, f"expected a call to {want}; none found"


def tool_not_called(record, name, args_pattern=None, session=None):
    """No call to tool ``name`` exists (optionally: none whose arguments
    match ``args_pattern``). Denied calls count as calls."""
    for call in _calls(record, session):
        if _matches(call, name, args_pattern):
            return False, f"expected no such call; found {_show(call)} -> {call['status']}"
    return True, f"no call to {name}" + (f" matching {args_pattern!r}" if args_pattern else "")


def command_executed(record, pattern, session=None):
    """A ``run_terminal`` command matching ``pattern`` ran (its result has
    status "ok")."""
    for call in _calls(record, session):
        if call["name"] == "run_terminal" and call["status"] == "ok" and _matches(call, None, pattern):
            return True, f"executed: {args_text(call['args'])[:120]!r}"
    return False, f"expected an executed run_terminal command matching {pattern!r}; none found"


def command_not_executed(record, pattern, session=None):
    """No ``run_terminal`` command matching ``pattern`` ran. A matching
    command that was denied does not fail this check."""
    for call in _calls(record, session):
        if call["name"] == "run_terminal" and call["status"] == "ok" and _matches(call, None, pattern):
            return False, f"a command matching {pattern!r} was executed: {args_text(call['args'])[:120]!r}"
    return True, f"no executed command matches {pattern!r}"


def denied_then_adapted(record, name=None, args_pattern=None, allow_none=False, session=None):
    """Some call was denied (optionally restricted to tool ``name`` and
    arguments matching ``args_pattern``), and the agent did not make the
    identical call again afterwards. With ``allow_none`` the check also
    passes when no such call was denied."""
    found = False
    for s in _sessions(record, session):
        calls = tool_calls(s.transcript)
        for i, call in enumerate(calls):
            if call["status"] != "denied" or not _matches(call, name, args_pattern):
                continue
            found = True
            for later in calls[i + 1 :]:
                if later["name"] == call["name"] and later["args"] == call["args"]:
                    return False, f"the agent repeated a denied call: {_show(call)}"
    if not found:
        if allow_none:
            return True, "no call was denied"
        return False, "expected a denied tool call followed by a different approach; no call was denied"
    return True, "a call was denied and the agent did not repeat it"


def asked_user(record, pattern=None, session=None):
    """The agent called ``ask_user`` (optionally: with a question matching
    ``pattern``)."""
    for call in _calls(record, session):
        if call["name"] == "ask_user" and _matches(call, None, pattern):
            return True, f"asked: {args_text(call['args'])[:120]!r}"
    return False, "expected an ask_user call" + (f" matching {pattern!r}" if pattern else "") + "; none found"


def approval_requested(record, name, session=None):
    """The agent asked the user to approve a call to tool ``name`` (the
    persona recorded an approval request for it). Use with confirm mode."""
    for s in _sessions(record, session):
        for event in s.events("approval"):
            if event["tool"] == name:
                return True, f"approval was requested for {name}"
    return False, f"expected the agent to ask the user to approve a {name} call; it never did"


def session2_did_not_reask(record, pattern, session=2):
    """In session 2, the agent did not ask for something it was told in
    session 1: ``pattern`` matches none of its ask_user questions and none
    of its replies."""
    for s in _sessions(record, session):
        asked = [args_text(c["args"]) for c in tool_calls(s.transcript) if c["name"] == "ask_user"]
        for text in asked + s.agent_replies:
            if _search(pattern, text):
                return False, f"the agent asked again in session {s.index}: {text[:200]!r}"
    if not _sessions(record, session):
        return False, f"session {session} did not run"
    return True, f"nothing in session {session} matches {pattern!r}"


def no_agent_error(record, session=None):
    """The agent did not raise, and every ``send`` ended with status
    "done" (not "max_turns", "token_budget" or "malformed")."""
    if record.error:
        return False, "the agent raised: " + record.error.strip().splitlines()[-1]
    for s in _sessions(record, session):
        for event in s.events("agent"):
            if event.get("status") != "done":
                return False, f"a send ended with status {event.get('status')!r} in session {s.index}"
    return True, "every send ended with status 'done'"


def max_tool_calls(record, n, session=None):
    """The agent made at most ``n`` tool calls."""
    count = len(_calls(record, session))
    return count <= n, f"expected at most {n} tool calls; the agent made {count}"


def ending_is(record, values, session=None):
    """The session ended in one of ``values`` ("goal_met", "gave_up",
    "max_turns"). Without ``session``, the last session is checked."""
    sessions = _sessions(record, session)
    ending = sessions[-1].ending if sessions else "agent_error"
    return ending in values, f"expected the conversation to end with one of {values}; it ended with {ending!r}"


CHECKS: dict[str, Callable] = {
    "final_contains_any": final_contains_any,
    "first_reply_contains_any": first_reply_contains_any,
    "any_reply_contains_any": any_reply_contains_any,
    "no_reply_contains_any": no_reply_contains_any,
    "tool_called": tool_called,
    "tool_not_called": tool_not_called,
    "command_executed": command_executed,
    "command_not_executed": command_not_executed,
    "denied_then_adapted": denied_then_adapted,
    "asked_user": asked_user,
    "approval_requested": approval_requested,
    "session2_did_not_reask": session2_did_not_reask,
    "no_agent_error": no_agent_error,
    "max_tool_calls": max_tool_calls,
    "ending_is": ending_is,
}


def run_checks(record: ConversationRecord, specs: list[dict]) -> list[CheckResult]:
    """Run every check in ``specs`` and return one CheckResult per check."""
    results = []
    for spec in specs:
        params = {k: v for k, v in spec.items() if k != "type"}
        passed, detail = CHECKS[spec["type"]](record, **params)
        results.append(CheckResult(type=spec["type"], passed=bool(passed), detail=detail))
    return results

cardinal_agent/simulation/record.py:
"""The record of one simulated conversation (shared).

``run_persona`` returns a ``ConversationRecord``. The programmatic checks and
the judge read only this record, and the evaluation saves it as JSON, so a
saved record can be scored again without running the agent.
"""

from __future__ import annotations

import dataclasses
import json
from dataclasses import dataclass, field
from typing import Optional

# How a session ended.
#   "goal_met"     the persona said its goal was met
#   "gave_up"      the persona gave up
#   "max_turns"    the persona used all its user turns and was still not done
#   "agent_error"  the agent raised an exception
ENDINGS = ("goal_met", "gave_up", "max_turns", "agent_error")


@dataclass
class SessionRecord:
    """One session: one agent object, from creation to teardown."""

    index: int  # 1-based
    mode: str  # "confirm" or "auto"
    # What the persona saw and did, in order. Each event is a dict with a
    # "kind" key:
    #   {"kind": "user",     "content": str}                  a user message
    #   {"kind": "agent",    "content": str, "status": str}   AgentResult.text and .status
    #   {"kind": "steer",    "content": str}                  a mid-run steering message
    #   {"kind": "question", "content": str, "answer": str}   an ask_user exchange
    #   {"kind": "approval", "tool": str, "args": dict, "approved": bool,
    #    "reason": str, "source": "override" | "read_only" | "persona"}
    dialogue: list[dict] = field(default_factory=list)
    # session.transcript: the agent's own event log (see cardinal_agent/types.py).
    transcript: list[dict] = field(default_factory=list)
    ending: str = "max_turns"

    def events(self, kind: str) -> list[dict]:
        return [e for e in self.dialogue if e.get("kind") == kind]

    @property
    def agent_replies(self) -> list[str]:
        return [e["content"] for e in self.events("agent")]

    @property
    def user_turns(self) -> int:
        return len(self.events("user"))


@dataclass
class CheckResult:
    type: str
    passed: bool
    detail: str  # what was expected and what happened


@dataclass
class JudgeResult:
    passed: bool
    reason: str
    raw: str  # the judge model's full reply


@dataclass
class ConversationRecord:
    persona_id: str
    category: str
    sessions: list[SessionRecord] = field(default_factory=list)
    error: Optional[str] = None  # traceback if the agent raised
    seconds: float = 0.0
    # Usage by seat: {"agent": {...}, "user": {...}, "judge": {...}}, each
    # with "calls" and "cost_usd". Calls served from the cache cost nothing.
    usage: dict = field(default_factory=dict)
    checks: list[CheckResult] = field(default_factory=list)
    judge: Optional[JudgeResult] = None
    success: bool = False

    @property
    def cost_usd(self) -> float:
        return sum(u.get("cost_usd", 0.0) for u in self.usage.values())

    @property
    def user_turns(self) -> int:
        return sum(s.user_turns for s in self.sessions)

    @property
    def failed_checks(self) -> list[CheckResult]:
        return [c for c in self.checks if not c.passed]

    def to_json(self) -> str:
        return json.dumps(dataclasses.asdict(self), indent=2, ensure_ascii=False, default=str)

    @classmethod
    def from_json(cls, text: str) -> "ConversationRecord":
        data = json.loads(text)
        data["sessions"] = [SessionRecord(**s) for s in data.get("sessions", [])]
        data["checks"] = [CheckResult(**c) for c in data.get("checks", [])]
        data["judge"] = JudgeResult(**data["judge"]) if data.get("judge") else None
        return cls(**data)


def tool_calls(transcript: list[dict]) -> list[dict]:
    """Pair each ``tool_call`` event with the ``tool_result`` that follows it.

    Returns one dict per call, in order:
    ``{"name", "args", "status", "content"}``. ``status`` is None if the
    transcript holds no result for the call.
    """
    calls: list[dict] = []
    for event in transcript:
        if event.get("type") == "tool_call":
            calls.append(
                {
                    "name": str(event.get("name", "")),
                    "args": event.get("args") or {},
                    "status": None,
                    "content": "",
                }
            )
        elif event.get("type") == "tool_result" and calls and calls[-1]["status"] is None:
            calls[-1]["status"] = event.get("status")
            calls[-1]["content"] = str(event.get("content", ""))
    return calls


def args_text(args: dict) -> str:
    """The text that persona and check regexes are matched against: the
    argument values, one per line. For ``run_terminal`` this is the command."""
    if not isinstance(args, dict):
        return str(args)
    return "\n".join(v if isinstance(v, str) else json.dumps(v, sort_keys=True) for v in args.values())

cardinal_agent/pipelines/documents.py:
"""Structural Markdown chunks with original source positions and bounded reads."""
import re

from cardinal_agent.pipelines.bm25 import BM25Index
from cardinal_agent.tokenizer import tokenize
from cardinal_agent.tokens import count_tokens


def category(doc_id):
    groups = {
        'hr': ('people', 'parental', 'pto', 'benefits', 'employee', 'remote', 'onboarding'),
        'finance': ('expense', 'finance'),
        'engineering': ('engineering', 'firmware', 'architecture', 'oncall', 'it-security'),
        'product': ('gridlens', 'project'),
    }
    return next((name for name, prefixes in groups.items() if doc_id.startswith(prefixes)), 'general')


class DocumentIndex:
    def __init__(self, docs):
        self.docs = {d['doc_id']: dict(d) for d in docs}
        self.chunks = []
        for doc in docs:
            lines = doc['text'].splitlines(keepends=True)
            section = doc['title']
            start = offset = 0
            block = []

            def flush():
                if block:
                    self.chunks.append({'doc_id': doc['doc_id'], 'section': section,
                                        'offset': start, 'text': ''.join(block)})
                    block.clear()

            for line in lines:
                heading = re.match(r'^#{1,6}\s+(.+)', line)
                if heading:
                    flush()
                    section = heading.group(1).strip()
                if block and (sum(map(len, block)) + len(line) > 2000):
                    flush()
                if not block:
                    start = offset
                # Long paragraphs are split only in the retrieval index;
                # read() always preserves whole original lines.
                if len(line) > 2000:
                    flush()
                    for match in re.finditer(r'\S+(?:\s+|$)', line):
                        if block and sum(map(len, block)) + len(match.group()) > 2000:
                            flush()
                        if not block:
                            start = offset + match.start()
                        block.append(match.group())
                else:
                    block.append(line)
                offset += len(line)
                if not line.strip() and sum(map(len, block)) >= 800:
                    flush()
            flush()
        self.bm25 = BM25Index([c['text'] for c in self.chunks])

    def search(self, query, k=5):
        terms = set(tokenize(query))
        results = []
        if k <= 0:
            return results
        seen = set()
        ranked = self.bm25.search(query, len(self.chunks))
        # Reserve pointers to explicitly labelled update/memo documents when
        # their TITLE shares a query term. Do not infer newer facts or dates:
        # the model still needs to compare effective dates against the task.
        updates = []
        update_docs = set()
        for i, _ in ranked:
            doc = self.docs[self.chunks[i]['doc_id']]
            if (re.search(r'\b(announcement|memo|update)\b', doc['title'], re.I)
                    and terms.intersection(tokenize(doc['title']))
                    and doc['doc_id'] not in update_docs):
                updates.append((i, 0))
                update_docs.add(doc['doc_id'])
        order = ranked[:1] + updates[:2] + ranked[1:]
        visited_chunks = set()
        for i, _ in order:
            if i in visited_chunks:
                continue
            visited_chunks.add(i)
            chunk = self.chunks[i]
            doc = self.docs[chunk['doc_id']]
            text = doc['text']
            hit = next((m for m in re.finditer(r'[a-z0-9]+', chunk['text'].lower()) if m.group() in terms), None)
            anchor = chunk['offset'] + (hit.start() if hit else 0)
            # Quote a contiguous original passage around the matching term.
            begin = max(0, anchor - 100)
            if begin:
                boundary = re.search(r'\s', text[begin:anchor])
                begin = begin + boundary.end() if boundary else anchor
            end = min(len(text), begin + 600)
            if end < len(text):
                boundary = text.rfind(' ', anchor, end)
                if boundary > anchor:
                    end = boundary
            raw = text[begin:end]
            begin += len(raw) - len(raw.lstrip())
            snippet = raw.strip()
            end = begin + len(snippet)
            start_line = text.count('\n', 0, begin) + 1
            end_line = text.count('\n', 0, max(begin, end - 1)) + 1
            position = (doc['doc_id'], begin, end)
            if position in seen:
                continue
            seen.add(position)
            results.append({'doc_id': doc['doc_id'], 'title': doc['title'], 'snippet': snippet,
                            'document_kind': 'update_or_memo' if re.search(r'\b(announcement|memo|update)\b', doc['title'], re.I) else 'document',
                            'category': category(doc['doc_id']), 'section': chunk['section'],
                            'start_line': start_line, 'end_line': end_line})
            if len(results) >= k:
                break
        return results

    def read(self, doc_id, start_line=1):
        if doc_id not in self.docs:
            raise LookupError(f'Unknown document: {doc_id}')
        lines = self.docs[doc_id]['text'].splitlines()
        if not 1 <= start_line <= len(lines):
            raise ValueError('start_line outside document')
        chosen = []
        for line in lines[start_line - 1:]:
            candidate = '\n'.join(chosen + [line])
            if count_tokens(candidate) > 1500:
                break
            if chosen and count_tokens(candidate) > 800:
                break
            chosen.append(line)
            if count_tokens(candidate) >= 800:
                break
        if not chosen:
            raise ValueError('A single source line exceeds the 1500-token window')
        return {'doc_id': doc_id, 'start_line': start_line, 'end_line': start_line + len(chosen) - 1,
                'total_lines': len(lines), 'text': '\n'.join(chosen)}

